/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_CASE_HEADER
   anchor      : HUB_CASE   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 2 -- opus_health_delta3, opus_health_legacy_v4
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CASE_HK
   hashdiff    : SAT_CASE_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
     SUBORDINATE WRITER on ASSIGNED_TO_REFERENCE: run opus_health_delta3, 1 writer(s), registry/ies HUB_CASE_BK__INWARDNO -- its value is DISCARDED wherever opus_health_legacy_v4 also writes the same key
   DECLARED SOURCE PRECEDENCE -- 1 attribute(s) are written by BOTH runs.
   Never a key change and never RECORD_SOURCE in a key: either would
   silently alter grain. Precedence is a VALUE choice, reversible by reload:
     ASSIGNED_TO_REFERENCE                        opus_health_legacy_v4 > opus_health_delta3
*/

with feeders as (
    select
        md5(upper('HUB_CASE|' || (HUB_CASE_BK__ALLOCATE_ID))) as HUB_CASE_HK
        , BUCKET_STATUS as CASE_STATUS
        , ALLOCATE_TO as ASSIGNED_TO_REFERENCE
        , 'BJAZ_HM_INWARD_AUTOALLOCATION' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_inward_autoallocation') }}
    where (nullif(trim(ALLOCATE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CASE|' || (HUB_CASE_BK__INWARDNO))) as HUB_CASE_HK
        , cast(null as varchar) as CASE_STATUS
        , ALLOCATE_TO as ASSIGNED_TO_REFERENCE
        , 'NG_FAX_INWARD_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ng_fax_inward_details') }}
    where (nullif('INWARD:' || nullif(trim(INWARDNO),''), 'INWARD:')) is not null
),

resolved as (
    select
        HUB_CASE_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CASE_STATUS end) as CASE_STATUS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSIGNED_TO_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ASSIGNED_TO_REFERENCE end)) as ASSIGNED_TO_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CASE_HK
),

hashed as (
    select
        *,
        case when CASE_STATUS is not null or ASSIGNED_TO_REFERENCE is not null
                     then md5(upper(coalesce(cast(CASE_STATUS as varchar), '') || '|' || coalesce(cast(ASSIGNED_TO_REFERENCE as varchar), '')))
                end as SAT_CASE_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CASE_HK is not null
  and SAT_CASE_HEADER_HASHDIFF is not null
